+      final fake = FakeStreamFunction([
+        toolTurn(const [
+          ToolCall(
+            id: 'c1',
+            name: 'bash',
+            arguments: {'command': 'stty ixon ixany < /dev/tty'},
+          ),
+          ToolCall(id: 'c2', name: 'bash', arguments: {'command': 'sleep 30'}),
+        ]),
+        textTurn('STEERED-OK'),
+      ]);
