+      );
+    });
+  });
+
+  group('TermiosGuard.dumpSettings', () {
+    test('returns the stty -a dump for /termios diagnostics', () async {
+      final tty = _FakeTty();
+      final guard = TermiosGuard(runner: tty.runner, hasTerminal: () => true);
