+      final result = await guard.reassert();
+      expect(
+        result.driftedFlags,
+        isEmpty,
+        reason: 'the cchars row names `discard` bare — not a drift',
+      );
+    });
+  });
+
+  group('TermiosGuard.dumpSettings', () {
+    test('returns the stty -a dump for /termios diagnostics', () async {
