+  _FakeTty({this.failAll = false, this.failProbe = false});
+
+  /// Flags currently ON (bare names); everything else reads as `-flag`.
+  /// Starts cleared (the post-boot state); tests corrupt it in place.
+  var enabled = <String>{};
