+        'intr = ^C; quit = ^\\; erase = ^?; kill = ^U; eof = ^D;\n'
+        'start = ^Q; stop = ^S; susp = ^Z; discard = ^O;\n'
+        '-parenb -parodd cs8 -hupcl -cstopb cread -clocal -crtscts\n'
