+
+  /// The flags a child had re-enabled and this pass cleared again,
+  /// e.g. `['ixon', 'ixany']`. Empty when the tty was already clean.
+  final List<String> driftedFlags;
+
+  bool get clearedDrift => driftedFlags.isNotEmpty;
+}
